import{_ as t,c as n,j as e,a as _,o as r}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第二百四十章 没有从痛苦中解脱出来","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/240第二百四十章 没有从痛苦中解脱出来.md","filePath":"meditation/巴利文大藏经/240第二百四十章 没有从痛苦中解脱出来.md"}'),o={name:"meditation/巴利文大藏经/240第二百四十章 没有从痛苦中解脱出来.md"};function l(s,a,i,d,p,c){return r(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第二百四十章-没有从痛苦中解脱出来",tabindex:"-1"},[_("第二百四十章 没有从痛苦中解脱出来 "),e("a",{class:"header-anchor",href:"#第二百四十章-没有从痛苦中解脱出来","aria-label":'Permalink to "第二百四十章 没有从痛苦中解脱出来"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部22相应29经/欢喜经(蕴相应/蕴篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！喜欢物质事物、物质身体的众生，他们就是在喜欢痛苦，这些喜欢物质事物、物质身体的众生，如来说他们：「无法从烦恼和痛苦中解脱出来。」 为什么这么说呢？因为物质事物是会衰败、灭亡、消失的，物质身体是会生病、衰老、死亡的，一旦世间的众生失去他们拥有的物质事物的时候，或者他们拥有的物质事物衰败、灭亡、消失的时候，他们就会产生烦恼和痛苦，这些物质事物给他们带来了多少快乐，他们失去这些物质事物的时候，这些物质事物衰败、灭亡、消失的时候，他们就会产生多少烦恼和痛苦。一旦物质身体生病、衰老、临死的时候，这些物质身体给他们带来了多少快乐，当物质身体生病、衰老、临死的时候，他们就会产生多少烦恼和痛苦。",-1),e("p",null,"比丘们！同样的道理，喜欢感受、念想、行为、认识、分别、判断的众生，他们就是在喜欢痛苦，这些喜欢感受、念想、行为、认识、分别、判断的众生，如来说他们：「无法从烦恼和痛苦中解脱出来。」为什么这么说呢？因为让他们快乐、开心、喜悦的感受、念想、行为、认识、分别、判断是会消退、灭尽、消失的，一旦感受、念想、行为、认识、分别、判断让世间的众生不满意、不开心、不快乐的时候，或者让世间众生满意、开心、快乐的感受、念想、行为、认识、分别、判断消退、灭尽、消失的时候，他们就会产生烦恼和痛苦，这些世间众生喜欢的感受、念想、行为、认识、分别、判断带给他们带来了多少快乐，当这些感受、念想、行为、认识、分别、判断让他们不满意、不开心、不快乐的时候，当他们喜欢的感受、念想、行为、认识、分别、判断消退、灭尽、消失的时候，他们就会产生多少的烦恼和痛苦。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(o,[["render",l]]);export{u as __pageData,f as default};
